import { useCallback, useEffect, useLayoutEffect, useRef, useState } from "react";
import { Link, useNavigate, useParams } from "react-router-dom";
import { ArrowUpRight, ChevronLeft, ChevronRight, Maximize2, Pause, Play } from "lucide-react";
import LazyVideo from "../components/LazyVideo";
import Button from "../components/Button";
import TransitionLink, { startPageTransition } from "../components/TransitionLink";
import { SymbolSwap } from "../components/motion";
import usePageMeta from "../hooks/usePageMeta";
import { PROJECTS, projectById } from "../data/projects";
import { loadProject, loadWork, prefersReducedMotion } from "../routes";
import "./ProjectPage.css";

const SWIPE = 56; // px of horizontal travel that counts as a swipe

// Moving between projects stays inside the viewer: a sideways slide in the direction of
// travel, the history entry replaced so Back still leaves the viewer in one step.
function useProjectNav(project) {
  const navigate = useNavigate();
  const index = PROJECTS.indexOf(project);

  const goTo = useCallback(
    (target, dir) => {
      if (!target || target.id === project.id) return;
      const way = dir || (PROJECTS.indexOf(target) > index ? "next" : "prev");
      startPageTransition(navigate, `/work/${target.id}`, { prepare: loadProject, dir: way, replace: true });
    },
    [navigate, project, index]
  );

  const prev = PROJECTS[(index - 1 + PROJECTS.length) % PROJECTS.length];
  const next = PROJECTS[(index + 1) % PROJECTS.length];
  return {
    index,
    goTo,
    goPrev: () => goTo(prev, "prev"),
    goNext: () => goTo(next, "next"),
  };
}

function Stage({ project, playing, onToggle, onPrev, onNext }) {
  const figure = useRef(null);
  const start = useRef(null);

  const onPointerDown = (e) => {
    if (e.pointerType === "mouse") return;
    start.current = { x: e.clientX, y: e.clientY };
  };
  const onPointerUp = (e) => {
    const s = start.current;
    start.current = null;
    if (!s) return;
    const dx = e.clientX - s.x;
    if (Math.abs(dx) > SWIPE && Math.abs(dx) > Math.abs(e.clientY - s.y) * 1.4) {
      if (dx < 0) onNext();
      else onPrev();
    }
  };

  const fullscreen = () => {
    const el = figure.current;
    if (!el) return;
    if (document.fullscreenElement) document.exitFullscreen?.().catch(() => {});
    else el.requestFullscreen?.().catch(() => {});
  };

  return (
    <figure
      ref={figure}
      className={`project-media ${project.video ? "is-video" : ""}`}
      onPointerDown={onPointerDown}
      onPointerUp={onPointerUp}
      onPointerCancel={() => (start.current = null)}
    >
      {project.video ? (
        <LazyVideo
          key={project.id}
          src={project.video}
          poster={project.image.large}
          play={playing}
          warm
          label={project.title}
          spinnerClassName="is-large"
          className="project-video"
          aria-label={`${project.title} gameplay video`}
        />
      ) : (
        <img
          src={project.image.large}
          srcSet={project.image.srcSet}
          sizes="(max-width: 1000px) 100vw, 70vw"
          width="1280"
          height="800"
          alt={`${project.title}, screenshot`}
          fetchPriority="high"
        />
      )}

      {/* Floating toolbar, like the controls in Photos */}
      <div className="pv-toolbar glass" role="toolbar" aria-label="Viewer controls">
        <button type="button" className="pv-tool" onClick={onPrev} aria-label="Previous project" aria-keyshortcuts="ArrowLeft">
          <ChevronLeft strokeWidth={2.2} aria-hidden="true" />
        </button>
        {project.video && (
          <button
            type="button"
            className="pv-tool"
            onClick={onToggle}
            aria-label={playing ? "Pause video" : "Play video"}
            aria-keyshortcuts="Space"
          >
            <SymbolSwap on={!playing} off={Pause} to={Play} weight="semibold" />
          </button>
        )}
        <button type="button" className="pv-tool" onClick={onNext} aria-label="Next project" aria-keyshortcuts="ArrowRight">
          <ChevronRight strokeWidth={2.2} aria-hidden="true" />
        </button>
        <span className="pv-tool-sep" aria-hidden="true" />
        <button type="button" className="pv-tool" onClick={fullscreen} aria-label="Full screen">
          <Maximize2 strokeWidth={2.1} aria-hidden="true" />
        </button>
      </div>
    </figure>
  );
}

// Every project as a thumbnail. A ring glides to the current one (during a project
// change the View Transition animates it; otherwise a CSS spring does).
function Filmstrip({ current, onPick }) {
  const ref = useRef(null);
  const ring = useRef(null);

  useLayoutEffect(() => {
    const active = ref.current?.querySelector('[aria-current="true"]');
    if (!active || !ring.current) return;
    // Place it instantly the first time; glide on every change after that.
    if (!ring.current.dataset.ready) requestAnimationFrame(() => ring.current && (ring.current.dataset.ready = "1"));
    ring.current.style.transform = `translate3d(${active.offsetLeft}px, ${active.offsetTop}px, 0)`;
    ring.current.style.width = `${active.offsetWidth}px`;
    ring.current.style.height = `${active.offsetHeight}px`;
  }, [current]);

  useEffect(() => {
    const active = ref.current?.querySelector('[aria-current="true"]');
    // Mid-transition, jump straight there so the captured strip already sits where it ends up.
    const instant = prefersReducedMotion() || "dir" in document.documentElement.dataset;
    active?.scrollIntoView({ block: "nearest", inline: "center", behavior: instant ? "auto" : "smooth" });
  }, [current]);

  return (
    <nav className="pv-strip" aria-label="All projects" ref={ref}>
      <span className="pv-ring" ref={ring} aria-hidden="true" />
      {PROJECTS.map((p) => {
        const active = p.id === current.id;
        return (
          <Link
            key={p.id}
            to={`/work/${p.id}`}
            replace
            className={`pv-thumb ${active ? "is-active" : ""}`}
            aria-current={active ? "true" : undefined}
            aria-label={p.title}
            title={p.title}
            onClick={(e) => {
              if (e.metaKey || e.ctrlKey || e.shiftKey || e.button !== 0) return;
              e.preventDefault();
              onPick(p);
            }}
          >
            <img src={p.image.src} width="640" height="400" alt="" loading="lazy" decoding="async" />
          </Link>
        );
      })}
    </nav>
  );
}

function Facts({ project }) {
  const facts = [
    { label: "Platform", value: project.platform },
    ...(project.status ? [{ label: "Status", value: project.status }] : []),
    ...project.stats,
  ];
  return (
    <dl className="pv-facts">
      {facts.map((fact) => (
        <div key={fact.label}>
          <dt>{fact.label}</dt>
          <dd>{fact.value}</dd>
        </div>
      ))}
    </dl>
  );
}

function ProjectPage() {
  const { id } = useParams();
  const project = projectById(id);
  const [playing, setPlaying] = useState(() => !prefersReducedMotion());
  // Opened directly (no page transition carrying it in): play a short entrance instead.
  const [entering, setEntering] = useState(
    () => typeof document !== "undefined" && !document.documentElement.dataset.vt && !prefersReducedMotion()
  );
  useEffect(() => {
    if (!entering) return undefined;
    const timer = setTimeout(() => setEntering(false), 1400);
    return () => clearTimeout(timer);
  }, [entering]);

  usePageMeta({
    title: project ? project.title : "Project not found",
    description: project ? `${project.shortDescription} ${project.category}.` : undefined,
    path: `/work/${id}`,
  });

  const nav = useProjectNav(project);
  const { goPrev, goNext } = nav;

  // ← → move between projects, space plays/pauses — unless typing or on a control.
  useEffect(() => {
    if (!project) return undefined;
    const onKey = (e) => {
      if (e.metaKey || e.ctrlKey || e.altKey) return;
      const el = document.activeElement;
      if (el && (el.tagName === "INPUT" || el.tagName === "TEXTAREA" || el.isContentEditable)) return;
      if (e.key === "ArrowRight") {
        e.preventDefault();
        goNext();
      } else if (e.key === "ArrowLeft") {
        e.preventDefault();
        goPrev();
      } else if (e.key === " " && project.video && !(el && (el.tagName === "BUTTON" || el.tagName === "A"))) {
        e.preventDefault();
        setPlaying((p) => !p);
      }
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  });

  if (!project) {
    return (
      <main id="main" className="site-main page not-found">
        <div className="shell not-found-inner">
          <span className="not-found-code">404</span>
          <h1 className="title-l">That project isn't in the folder.</h1>
          <Button as={Link} variant="primary" to="/work">
            Browse all projects
          </Button>
        </div>
      </main>
    );
  }

  const commissionable = project.stats.length > 0;
  const position = `${String(nav.index + 1).padStart(2, "0")} / ${String(PROJECTS.length).padStart(2, "0")}`;

  return (
    <main id="main" className={`site-main project-view ${entering ? "is-entering" : ""}`}>
      <div className="shell pv-stage">
        <aside className="pv-info" key={`info-${project.id}`}>
          <div className="pv-top">
            <TransitionLink className="pv-back" to="/work" prepare={loadWork} morphTo={project.id}>
              <ChevronLeft aria-hidden="true" strokeWidth={2.2} />
              Work
            </TransitionLink>
            <span className="pv-count" aria-label={`Project ${nav.index + 1} of ${PROJECTS.length}`}>
              {position}
            </span>
          </div>

          <div className="pv-body">
            <p className="pv-kind">{project.category}</p>
            <h1 className="pv-title">{project.title}</h1>
            <p className="pv-summary">{project.summary}</p>
            <Facts project={project} />
          </div>

          {(project.url || commissionable) && (
            <div className="pv-actions">
              {project.url && (
                <Button variant="primary" href={project.url} icon={ArrowUpRight}>
                  {project.urlLabel || "Visit"}
                </Button>
              )}
              {commissionable && (
                <Button as={TransitionLink} variant={project.url ? "secondary" : "primary"} to="/#contact">
                  Commission something like this
                </Button>
              )}
            </div>
          )}
        </aside>

        <section className="pv-main" aria-label={`${project.title} media`}>
          <Stage
            project={project}
            playing={playing}
            onToggle={() => setPlaying((p) => !p)}
            onPrev={goPrev}
            onNext={goNext}
          />
          <Filmstrip current={project} onPick={(p) => nav.goTo(p)} />
        </section>
      </div>
    </main>
  );
}

export default ProjectPage;
